"use client";
import { useEffect,useState } from "react";
import { useRouter } from "next/navigation";
import { ArrowUpRight, BarChart3, Building2, ChevronRight, CircleDollarSign, Clock3, Handshake, Megaphone, Plane, ShieldCheck, Ticket, Trophy, Users, X } from "lucide-react";
import { addDays,advanceEventDay,contactUnlocked,daysBetween,eventDayChecks,flightProgramIssues,flightProgramReady,flightSlotEnd,formatDate,loadGame,money,monthlyPayroll,negotiateParticipantOffer,negotiateSponsorOffer,nextIncident,nextSeasonBudget,operationReadiness,participantBaseTotal,participantNegotiationRisk,readiness,resolveEventDayIssue,saveGame,scales,seasonMilestones,sortedFlightProgram,sponsorCommitmentProgress,sponsorConflict,sponsorNegotiationRisk,sponsorOffer,sponsorPenalty,startEventDaySimulation,startNextSeason,ticketDemandPerDay,totalSponsorPenalty,unlockedContactCount,type Contact,type Department,type InfrastructureProject,type MarketingCampaign,type SaveGame,type ScaleId,type Sponsor,type Status } from "../lib/game";
import { t } from "../lib/i18n";
import ThemeToggle from "./ThemeToggle";
import styles from "../app/page.module.css";

const sections=[
 ["centrum","center",BarChart3],["operacje","operations",ShieldCheck],["program","program",Clock3],["uczestnicy","participants",Plane],["sponsorzy","sponsors",Handshake],["zespol","team",Users],["infrastruktura","infrastructure",Building2],["bilety","tickets",Ticket],["marketing","marketing",Megaphone],["finanse","finance",CircleDollarSign],["event-day","eventDay",Trophy]
] as const;

const modules:Record<string,{eyebrow:string;title:string;description:string;items:string[]}>={
 operacje:{eyebrow:"OPERACJE",title:"Gotowość operacyjna",description:"Planowanie bezpieczeństwa, lotniska i przepływu wydarzenia.",items:["Plan operacyjny lotniska","Strefa pokazów i bezpieczeństwo","Harmonogram prób i odpraw"]},
 sponsorzy:{eyebrow:"KOMERCJA",title:"Sponsorzy i partnerzy",description:"Buduj przychody komercyjne bez utraty kontroli nad zobowiązaniami.",items:["Lista potencjalnych partnerów","Pakiety sponsorskie","Świadczenia i terminy"]},
 zespol:{eyebrow:"ORGANIZACJA",title:"Zespół i departamenty",description:"Kompetencje organizacji będą wpływać na tempo i jakość przygotowań.",items:["Operacje lotnicze","Bezpieczeństwo i logistyka","Komercja i komunikacja"]},
 infrastruktura:{eyebrow:"LOTNISKO",title:"Infrastruktura wydarzenia",description:"Rozwijaj przestrzeń potrzebną uczestnikom, widzom i służbom.",items:["Płyta i parking statków powietrznych","Strefy publiczności","Zaplecze operacyjne"]},
 bilety:{eyebrow:"SPRZEDAŻ",title:"Bilety i frekwencja",description:"Cena, pojemność i tempo sprzedaży będą kształtować wynik wydarzenia.",items:["Cennik i pule biletów","Prognoza frekwencji","Przychód ze sprzedaży"]},
 marketing:{eyebrow:"KOMUNIKACJA",title:"Marketing wydarzenia",description:"Buduj zasięg i popyt, reagując na siłę programu i moment sezonu.",items:["Kampanie promocyjne","Media i partnerzy","Rozpoznawalność wydarzenia"]}
};

export default function GamePage({section}:{section:string}){
 const router=useRouter(); const [game,setGame]=useState<SaveGame|null>(null); const [selected,setSelected]=useState<number|null>(null);
 useEffect(()=>{const g=loadGame();if(!g){router.replace("/nowa-kariera");return}setGame(g)},[router]);
 useEffect(()=>{if(game)saveGame(game)},[game]);
 const days=game?daysBetween(game.currentDate,game.career.eventDate):0;
 const confirmed=game?.contacts.filter(c=>c.status==="confirmed").length??0;
 const active=sections.some(x=>x[0]===section)?section:"centrum";
 const advance=(amount:number)=>setGame(current=>{if(!current)return current;if(current.activeIncident)return {...current,feed:["Najpierw rozwiąż aktywne zdarzenie sezonowe.",...current.feed].slice(0,10)};
  const remaining=daysBetween(current.currentDate,current.career.eventDate);
  const nextDate=addDays(current.currentDate,Math.min(amount,remaining));
  const oldDays=remaining;
  const newDays=daysBetween(nextDate,current.career.eventDate);
  const contacts=current.contacts.map(c=>{
    if(c.status==="invited"&&c.replyAt&&c.replyAt<=nextDate){
      if(c.id===4)return {...c,status:"declined" as Status,replyAt:null};
      const offerExpiresAt=addDays(c.replyAt,10);
      if(offerExpiresAt<nextDate)return {...c,status:"declined" as Status,replyAt:null,offerExpiresAt};
      return {...c,status:"interested" as Status,replyAt:null,offerExpiresAt,negotiationRound:0,agreedDiscount:0};
    }
    if(c.status==="interested"&&c.offerExpiresAt&&c.offerExpiresAt<nextDate)return {...c,status:"declined" as Status};
    return c;
  });
  const participantResponses=contacts.flatMap((c,i)=>{const before=current.contacts[i];if(c.status===before.status)return [];if(c.status==="interested")return [`${c.name}: pozytywna odpowiedź. Oferta ważna do ${c.offerExpiresAt?formatDate(c.offerExpiresAt):"—"}.`];if(before.status==="interested"&&c.status==="declined")return [`${c.name}: oferta wygasła bez podpisania umowy.`];return [`${c.name}: zespół nie jest dostępny w tym sezonie.`]});
  const confirmedActs=contacts.filter(c=>c.status==="confirmed").length;
  const sponsors=current.sponsors.map(sp=>{
    if(sp.status==="contacted"&&sp.replyAt&&sp.replyAt<=nextDate){
      if(current.reputation<sp.minReputation)return {...sp,status:"declined" as const,replyAt:null};
      return {...sp,status:"offered" as const,offer:sponsorOffer(sp,confirmedActs),replyAt:null,offerExpiresAt:addDays(sp.replyAt,12),negotiationRound:0,negotiated:false};
    }
    if(sp.status==="offered"&&sp.offerExpiresAt&&sp.offerExpiresAt<nextDate)return {...sp,status:"declined" as const};
    return sp;
  });
  const sponsorResponses=sponsors.flatMap((sp,i)=>{const before=current.sponsors[i];if(sp.status===before.status)return [];if(sp.status==="offered")return [`${sp.name}: oferta ${money(sp.offer??0)} ważna do ${sp.offerExpiresAt?formatDate(sp.offerExpiresAt):"—"}.`];if(before.status==="offered"&&sp.status==="declined")return [`${sp.name}: oferta sponsorska wygasła.`];return [`${sp.name}: propozycja współpracy została odrzucona.`]});
  const crossed=seasonMilestones.filter(m=>oldDays>m.days&&newDays<=m.days&&!current.milestonesSeen.includes(m.days));
  const advancedDays=Math.max(0,oldDays-newDays);
  const payroll=Math.round(monthlyPayroll(current)*advancedDays/30);
  const payrollNote=payroll>0?[`Koszt zespołu za ${advancedDays} dni: ${money(payroll)}.`]:[];
  const dailyDemand=ticketDemandPerDay(current);
  const remainingTickets=Math.max(0,current.ticketing.capacity-current.ticketing.sold);
  const soldNow=current.ticketing.salesOpened?Math.min(remainingTickets,dailyDemand*advancedDays):0;
  const ticketRevenue=soldNow*current.ticketing.price;
  const ticketNote=soldNow>0?[`Sprzedaż biletów: ${soldNow.toLocaleString("pl-PL")} szt. · przychód ${money(ticketRevenue)}.`]:[];
  const feed=[...crossed.map(m=>m.text),...sponsorResponses,...participantResponses,...ticketNote,...payrollNote,...current.feed].slice(0,10);
  let transactions=current.transactions;
  if(payroll>0)transactions=[{id:`payroll-${nextDate}-${Date.now()}`,date:nextDate,label:`Koszt zespołu (${advancedDays} dni)`,amount:-payroll,category:"operations" as const},...transactions];
  if(ticketRevenue>0)transactions=[{id:`tickets-${nextDate}-${Date.now()}`,date:nextDate,label:`Sprzedaż biletów (${soldNow.toLocaleString("pl-PL")} szt.)`,amount:ticketRevenue,category:"ticketing" as const},...transactions];
  const incident=nextIncident(current,oldDays,newDays);
  return {...current,currentDate:nextDate,cash:current.cash-payroll+ticketRevenue,contacts,sponsors,ticketing:{...current.ticketing,sold:current.ticketing.sold+soldNow},feed:incident?[`${incident.kind==="crisis"?"KRYZYS":"SZANSA"}: ${incident.title}`,...feed].slice(0,10):feed,transactions,milestonesSeen:[...current.milestonesSeen,...crossed.map(m=>m.days)],activeIncident:incident??current.activeIncident,incidentsSeen:incident?[...current.incidentsSeen,incident.id]:current.incidentsSeen}
 }); const invite=(id:number)=>setGame(current=>{if(!current)return current;const contact=current.contacts.find(c=>c.id===id);if(!contact)return current;if(!contactUnlocked(current,contact))return {...current,feed:[`${contact.name}: kontakt pozostaje poza zasięgiem obecnej reputacji kariery.`,...current.feed].slice(0,10)};return {...current,contacts:current.contacts.map(c=>c.id===id?{...c,status:"invited",replyAt:addDays(current.currentDate,4),offerExpiresAt:null,negotiationRound:0,agreedDiscount:0}:c),feed:[`Wysłano zaproszenie do ${contact.name}. Odpowiedź spodziewana jest w ciągu 4 dni.`,...current.feed].slice(0,10)}});
 const sign=(id:number)=>setGame(current=>{if(!current)return current;const c=current.contacts.find(x=>x.id===id);if(!c||c.status!=="interested")return current;if(c.offerExpiresAt&&c.offerExpiresAt<current.currentDate)return {...current,contacts:current.contacts.map(x=>x.id===id?{...x,status:"declined"}:x),feed:[`${c.name}: nie można podpisać — oferta wygasła.`,...current.feed].slice(0,10)};const total=Math.round(participantBaseTotal(c)*(1-c.agreedDiscount/100));if(total>current.cash)return {...current,feed:["Umowa zablokowana: dostępne środki są niewystarczające.",...current.feed].slice(0,10)};setSelected(null);return {...current,cash:current.cash-total,contacts:current.contacts.map(x=>x.id===id?{...x,status:"confirmed",offerExpiresAt:null}:x),feed:[`${c.name}: podpisano umowę na ${money(total)}${c.agreedDiscount>0?` po rabacie ${c.agreedDiscount}%`:""}.`,...current.feed].slice(0,10),transactions:[{id:`participant-${id}-${Date.now()}`,date:current.currentDate,label:`Umowa: ${c.name}`,amount:-total,category:"participant"},...current.transactions]}}); 
 const negotiateParticipant=(id:number)=>setGame(current=>{if(!current)return current;const c=current.contacts.find(x=>x.id===id);if(!c||c.status!=="interested"||c.negotiationRound>=2)return current;if(c.offerExpiresAt&&c.offerExpiresAt<current.currentDate)return {...current,contacts:current.contacts.map(x=>x.id===id?{...x,status:"declined"}:x),feed:[`${c.name}: oferta wygasła przed kolejną rundą negocjacji.`,...current.feed].slice(0,10)};const outcome=negotiateParticipantOffer(current,c);if(outcome.walked){setSelected(null);return {...current,contacts:current.contacts.map(x=>x.id===id?{...x,status:"declined",negotiationRound:outcome.nextRound}:x),feed:[`${c.name}: zespół wycofał ofertę po zbyt agresywnej negocjacji.`,...current.feed].slice(0,10)}};return {...current,contacts:current.contacts.map(x=>x.id===id?{...x,negotiationRound:outcome.nextRound,agreedDiscount:outcome.discount}:x),feed:[`${c.name}: runda ${outcome.nextRound} zakończona sukcesem. Rabat wzrósł do ${outcome.discount}%.`,...current.feed].slice(0,10)}});
 const resolveIncident=(choiceId:"a"|"b")=>setGame(current=>{if(!current||!current.activeIncident)return current;const incident=current.activeIncident;const choice=incident.choices.find(c=>c.id===choiceId);if(!choice)return current;const effect=choice.effect;const deltaCash=effect.cash??0;const deltaRep=effect.reputation??0;const deltaAwareness=effect.awareness??0;const deltaReadiness=effect.readiness??0;const transactions=deltaCash!==0?[{id:`incident-${incident.id}-${Date.now()}`,date:current.currentDate,label:`${incident.title}: ${choice.label}`,amount:deltaCash,category:"incident" as const},...current.transactions]:current.transactions;return {...current,cash:current.cash+deltaCash,reputation:Math.max(0,Math.min(100,current.reputation+deltaRep)),awareness:Math.max(0,Math.min(100,current.awareness+deltaAwareness)),crisisReadiness:Math.max(-20,Math.min(20,current.crisisReadiness+deltaReadiness)),activeIncident:null,transactions,feed:[`${incident.title}: wybrano „${choice.label}”.`,...current.feed].slice(0,10)}}); const addToFlightProgram=(contactId:number)=>setGame(current=>{if(!current)return current;const contact=current.contacts.find(c=>c.id===contactId);if(!contact||contact.status!=="confirmed"||current.flightProgram.some(slot=>slot.contactId===contactId))return current;const sorted=[...current.flightProgram].sort((a,b)=>a.start.localeCompare(b.start));const start=sorted.length?flightSlotEnd(sorted[sorted.length-1]):"10:00";return {...current,flightProgram:[...current.flightProgram,{id:`slot-${contactId}`,contactId,start,duration:15,buffer:10}],feed:[`${contact.name}: dodano do programu lotniczego na ${start}.`,...current.feed].slice(0,10)}}); 
 const updateFlightSlot=(id:string,patch:{start?:string;duration?:number;buffer?:number})=>setGame(current=>current?{...current,flightProgram:current.flightProgram.map(slot=>slot.id===id?{...slot,...patch,duration:patch.duration!==undefined?Math.max(5,Math.min(40,patch.duration)):slot.duration,buffer:patch.buffer!==undefined?Math.max(5,Math.min(30,patch.buffer)):slot.buffer}:slot)}:current);
 const removeFlightSlot=(id:string)=>setGame(current=>current?{...current,flightProgram:current.flightProgram.filter(slot=>slot.id!==id)}:current); const contactSponsor=(id:number)=>setGame(current=>{if(!current)return current;const sp=current.sponsors.find(x=>x.id===id);if(!sp)return current;const conflict=sponsorConflict(current,sp);if(conflict)return {...current,feed:[`${sp.name}: rozmowy zablokowane przez wyłączność ${conflict.name}.`,...current.feed].slice(0,10)};return {...current,sponsors:current.sponsors.map(x=>x.id===id?{...x,status:"contacted",replyAt:addDays(current.currentDate,5),offer:null,offerExpiresAt:null,negotiationRound:0,negotiated:false}:x),feed:[`Wysłano propozycję współpracy do ${sp.name}. Odpowiedź spodziewana jest w ciągu 5 dni.`,...current.feed].slice(0,10)}});
 const negotiateSponsor=(id:number)=>setGame(current=>{if(!current)return current;const sp=current.sponsors.find(x=>x.id===id);if(!sp||sp.status!=="offered"||!sp.offer||sp.negotiationRound>=2)return current;if(sp.offerExpiresAt&&sp.offerExpiresAt<current.currentDate)return {...current,sponsors:current.sponsors.map(x=>x.id===id?{...x,status:"declined"}:x)};const outcome=negotiateSponsorOffer(current,sp);if(outcome.walked)return {...current,sponsors:current.sponsors.map(x=>x.id===id?{...x,status:"declined",negotiationRound:outcome.nextRound}:x),feed:[`${sp.name}: sponsor wycofał ofertę po zbyt agresywnej rundzie negocjacji.`,...current.feed].slice(0,10)};return {...current,sponsors:current.sponsors.map(x=>x.id===id?{...x,offer:outcome.offer,negotiationRound:outcome.nextRound,negotiated:outcome.nextRound>=2}:x),feed:[`${sp.name}: runda ${outcome.nextRound} zakończona. Aktualna oferta: ${money(outcome.offer)}.`,...current.feed].slice(0,10)}}); 
 const acceptSponsor=(id:number)=>setGame(current=>{if(!current)return current;const sp=current.sponsors.find(x=>x.id===id);if(!sp||sp.status!=="offered"||!sp.offer)return current;const conflict=sponsorConflict(current,sp);if(conflict)return {...current,feed:[`${sp.name}: umowa zablokowana przez wyłączność ${conflict.name}.`,...current.feed].slice(0,10)};if(sp.offerExpiresAt&&sp.offerExpiresAt<current.currentDate)return {...current,sponsors:current.sponsors.map(x=>x.id===id?{...x,status:"declined"}:x),feed:[`${sp.name}: oferta wygasła przed podpisaniem.`,...current.feed].slice(0,10)};return {...current,cash:current.cash+sp.offer,reputation:Math.min(100,current.reputation+2),sponsors:current.sponsors.map(x=>x.id===id?{...x,status:"partner",offerExpiresAt:null}:x),feed:[`${sp.name}: podpisano umowę sponsorską na ${money(sp.offer)}. Zobowiązania są aktywne do Event Day.`,...current.feed].slice(0,10),transactions:[{id:`sponsor-${id}-${Date.now()}`,date:current.currentDate,label:`Sponsor: ${sp.name}`,amount:sp.offer,category:"sponsor"},...current.transactions]}});
 const upgradeDepartment=(id:Department["id"])=>setGame(current=>{if(!current)return current;const d=current.departments.find(x=>x.id===id);if(!d||d.level>=4)return current;const cost=Math.round(d.upgradeCost*(1+(d.level-1)*.45));if(cost>current.cash)return {...current,feed:[`Nie można rozwinąć departamentu ${d.name}: niewystarczające środki.`,...current.feed].slice(0,10)};return {...current,cash:current.cash-cost,reputation:Math.min(100,current.reputation+1),departments:current.departments.map(x=>x.id===id?{...x,level:x.level+1}:x),feed:[`${d.name}: departament rozwinięty do poziomu ${d.level+1}.`,...current.feed].slice(0,10),transactions:[{id:`team-${id}-${Date.now()}`,date:current.currentDate,label:`Rozwój zespołu: ${d.name}`,amount:-cost,category:"operations"},...current.transactions]}}); 
 const completeOperation=(id:string)=>setGame(current=>{if(!current)return current;const op=current.operations.find(x=>x.id===id);if(!op||op.completed)return current;const dept=current.departments.find(x=>x.id===op.department);if(!dept||dept.level<op.requiredLevel)return {...current,feed:[`${op.title}: wymagany poziom departamentu ${op.requiredLevel}.`,...current.feed].slice(0,10)};if(op.cost>current.cash)return {...current,feed:[`${op.title}: niewystarczające środki na realizację zadania.`,...current.feed].slice(0,10)};return {...current,cash:current.cash-op.cost,reputation:Math.min(100,current.reputation+1),operations:current.operations.map(x=>x.id===id?{...x,completed:true}:x),feed:[`Zakończono zadanie operacyjne: ${op.title}.`,...current.feed].slice(0,10),transactions:[{id:`operation-${id}-${Date.now()}`,date:current.currentDate,label:`Operacje: ${op.title}`,amount:-op.cost,category:"operations"},...current.transactions]}});
 const buildInfrastructure=(id:string)=>setGame(current=>{if(!current)return current;const project=current.infrastructure.find(x=>x.id===id);if(!project||project.completed)return current;const dept=current.departments.find(x=>x.id===project.department);if(!dept||dept.level<project.requiredLevel)return {...current,feed:[`${project.name}: wymagany poziom departamentu ${project.requiredLevel}.`,...current.feed].slice(0,10)};if(project.cost>current.cash)return {...current,feed:[`${project.name}: niewystarczające środki na inwestycję.`,...current.feed].slice(0,10)};return {...current,cash:current.cash-project.cost,reputation:Math.min(100,current.reputation+1),infrastructure:current.infrastructure.map(x=>x.id===id?{...x,completed:true}:x),feed:[`Infrastruktura gotowa: ${project.name}. Gotowość wydarzenia wzrosła.`,...current.feed].slice(0,10),transactions:[{id:`infra-${id}-${Date.now()}`,date:current.currentDate,label:`Infrastruktura: ${project.name}`,amount:-project.cost,category:"infrastructure"},...current.transactions]}});
 const runCampaign=(id:string)=>setGame(current=>{if(!current)return current;const campaign=current.marketing.find(x=>x.id===id);if(!campaign||campaign.completed)return current;const dept=current.departments.find(d=>d.id==="marketing");if(!dept||dept.level<campaign.requiredLevel)return {...current,feed:[`${campaign.name}: wymagany poziom Marketingu ${campaign.requiredLevel}.`,...current.feed].slice(0,10)};if(campaign.cost>current.cash)return {...current,feed:[`${campaign.name}: niewystarczające środki na kampanię.`,...current.feed].slice(0,10)};return {...current,cash:current.cash-campaign.cost,awareness:Math.min(100,current.awareness+campaign.awareness),reputation:Math.min(100,current.reputation+1),marketing:current.marketing.map(x=>x.id===id?{...x,completed:true}:x),feed:[`Zrealizowano kampanię: ${campaign.name}. Rozpoznawalność wydarzenia wzrosła.`,...current.feed].slice(0,10),transactions:[{id:`marketing-${id}-${Date.now()}`,date:current.currentDate,label:`Marketing: ${campaign.name}`,amount:-campaign.cost,category:"marketing"},...current.transactions]}}); 
 const openTicketSales=()=>setGame(current=>{if(!current||current.ticketing.salesOpened)return current;const confirmed=current.contacts.filter(c=>c.status==="confirmed").length;if(confirmed<1)return {...current,feed:["Nie można otworzyć sprzedaży bez potwierdzonego uczestnika programu.",...current.feed].slice(0,10)};return {...current,ticketing:{...current.ticketing,salesOpened:true},feed:[`Uruchomiono sprzedaż biletów w cenie ${money(current.ticketing.price)}.`,...current.feed].slice(0,10)}});
 const adjustTicketPrice=(delta:number)=>setGame(current=>current?{...current,ticketing:{...current.ticketing,price:Math.max(39,Math.min(249,current.ticketing.price+delta))},feed:[`Cena biletu została ustawiona na ${money(Math.max(39,Math.min(249,current.ticketing.price+delta)))}.`,...current.feed].slice(0,10)}:current);
 const runEventDay=()=>setGame(current=>current?startEventDaySimulation(current):current); const stepEventDay=()=>setGame(current=>current?advanceEventDay(current):current); const decideEventDay=(choice:"a"|"b")=>setGame(current=>current?resolveEventDayIssue(current,choice):current); const beginNextSeason=(scaleId:ScaleId)=>setGame(current=>current?startNextSeason(current,scaleId):current);

 if(!game)return <main className={styles.loading}><Plane size={18}/><span>Wczytywanie centrum operacyjnego…</span></main>;
 return <main className={styles.gameShell}>
  <aside className={styles.sidebar}><div className={styles.gameBrand}><span className={styles.mark}><Plane size={17}/></span><div><b>AIRSHOW MANAGER</b><small>SEZON {String(game.season).padStart(2,"0")}</small></div></div><nav>{sections.map(([slug,key,Icon])=><button key={slug} onClick={()=>router.push(`/gra/${slug}`)} className={active===slug?styles.navActive:""}><Icon size={16}/><span>{t(game.locale,`nav.${key}` as any)}</span></button>)}</nav><div className={styles.sidebarActions}><ThemeToggle/><button type="button" onClick={()=>router.push("/")}>Strona główna</button></div><div className={styles.eventChip}><span>AKTYWNE WYDARZENIE</span><b>{game.career.eventName}</b><small>{formatDate(game.career.eventDate)}</small></div></aside>
  <section className={styles.gameMain}><header className={styles.gameHeader}><div><span>{active==="centrum"?"CENTRUM DOWODZENIA":t(game.locale,`nav.${sections.find(x=>x[0]===active)?.[1]}` as any).toUpperCase()}</span><h1>{game.career.eventName}</h1><p>{game.career.location} · {formatDate(game.career.eventDate)}</p></div><div className={styles.clock}><div><b>{days}</b><span>DNI DO POKAZU</span></div><div><button onClick={()=>advance(1)}>+1 dzień</button><button onClick={()=>advance(7)}>+7 dni</button></div></div></header>
  {active==="centrum"&&<Center game={game}/>}
  {active==="uczestnicy"&&<Participants game={game} invite={invite} open={setSelected}/>}
  {active==="finanse"&&<Finance game={game}/>}
  {active==="sponsorzy"&&<Sponsors game={game} contact={contactSponsor} negotiate={negotiateSponsor} accept={acceptSponsor}/>}
  {active==="zespol"&&<Team game={game} upgrade={upgradeDepartment}/>}
  {active==="operacje"&&<Operations game={game} complete={completeOperation}/>}  {active==="program"&&<FlightProgram game={game} add={addToFlightProgram} update={updateFlightSlot} remove={removeFlightSlot}/>}
  {active==="infrastruktura"&&<Infrastructure game={game} build={buildInfrastructure}/>}
  {active==="marketing"&&<Marketing game={game} run={runCampaign}/>}
  {active==="bilety"&&<Tickets game={game} open={openTicketSales} adjust={adjustTicketPrice}/>}
  {active==="event-day"&&<EventDay game={game} run={runEventDay} step={stepEventDay} decide={decideEventDay} nextSeason={beginNextSeason}/>}
  {!["centrum","uczestnicy","finanse","sponsorzy","zespol","operacje","program","infrastruktura","marketing","bilety","event-day"].includes(active)&&<Module section={active}/>}
  </section>
  {selected&&<Contract game={game} contact={game.contacts.find(c=>c.id===selected)!} close={()=>setSelected(null)} sign={sign} negotiate={negotiateParticipant}/>}
 </main>
}

function Center({game}:{game:SaveGame}){const days=daysBetween(game.currentDate,game.career.eventDate);const confirmed=game.contacts.filter(c=>c.status==="confirmed").length;const partners=game.sponsors.filter(s=>s.status==="partner").length;const ready=readiness(game);const nextGoal=confirmed<2?"Potwierdź co najmniej 2 uczestników":partners<1?"Pozyskaj pierwszego sponsora":!game.ticketing.salesOpened?"Otwórz sprzedaż biletów":"Rozwijaj operacje i popyt";return <div className={styles.dashboard}>
 <section className={styles.statusRail}><div><span>FAZA SEZONU</span><b>{days>240?"Fundamenty":days>90?"Rozwój programu":"Finalizacja"}</b></div><div><span>NAJBLIŻSZY CEL</span><b>{nextGoal}</b></div><div><span>RYZYKO BUDŻETOWE</span><b className={game.cash/game.career.budget>.45?styles.good:styles.warn}>{game.cash/game.career.budget>.45?"Niskie":"Podwyższone"}</b></div></section>
 <section className={styles.kpiGrid}><Kpi label="Dostępne środki" value={money(game.cash)} note={`${Math.round(game.cash/game.career.budget*100)}% budżetu startowego`}/><Kpi label="Potwierdzony program" value={String(confirmed)} note="podpisane umowy"/><Kpi label="Reputacja" value={game.reputation+" / 100"} note="poziom organizatora"/><Kpi label="Gotowość" value={ready+"%"} note="stan całej organizacji"/></section>
 <section className={styles.dashboardGrid}><article className={styles.surface}><PanelHead overline="PRIORYTETY" title="Najbliższe decyzje" meta="4 OTWARTE"/>{[["01","Potwierdź uczestnika","Program lotniczy"],["02","Zbuduj bazę sponsorów","Komercja"],["03","Ustal strategię biletową","Sprzedaż"],["04","Przygotuj plan operacyjny","Operacje"]].map(([n,title,area])=><div className={styles.priority} key={n}><span>{n}</span><div><b>{title}</b><small>{area}</small></div><ChevronRight size={15}/></div>)}</article>
 <article className={styles.surface}><PanelHead overline="GOTOWOŚĆ" title="Obszary organizacji" meta={ready+"%"}/>{[["Program",Math.min(100,confirmed*24)],["Finanse",Math.round(game.cash/game.career.budget*100)],["Operacje",12],["Komunikacja",game.awareness]].map(([name,value])=><div className={styles.readinessRow} key={name as string}><div><span>{name}</span><b>{value}%</b></div><i><em style={{width:`${value}%`}}/></i></div>)}</article></section>
 <section className={styles.surface}><PanelHead overline="DZIENNIK" title="Ostatnie wydarzenia" meta={formatDate(game.currentDate)}/><div className={styles.activity}>{game.feed.map((x,i)=><div key={i}><span>D-{days}</span><p>{x}</p></div>)}</div></section>
 </div>}

function Participants({game,invite,open}:{game:SaveGame;invite:(id:number)=>void;open:(id:number)=>void}){const unlocked=unlockedContactCount(game);const confirmed=game.contacts.filter(c=>c.status==="confirmed").length;return <div className={styles.modulePage}><ModuleHeader eyebrow="PROGRAM LOTNICZY" title="Rynek uczestników" description="Rozwijaj reputację organizatora, aby uzyskać dostęp do coraz bardziej prestiżowych zespołów. Mocniejszy program oznacza większe koszty, ale też większy potencjał wydarzenia." meta={`${unlocked}/${game.contacts.length} kontaktów dostępnych`}/><section className={styles.participantSummary}><Kpi label="Dostępny rynek" value={String(unlocked)} note="kontaktów spełnia wymagania"/><Kpi label="Potwierdzeni" value={String(confirmed)} note="aktywne umowy"/><Kpi label="Reputacja" value={game.reputation+" / 100"} note="odblokowuje nowe kontakty"/><Kpi label="Sezon kariery" value={String(game.season).padStart(2,"0")} note="część kontaktów wymaga doświadczenia"/></section><div className={styles.tableHeader}><span>ZESPÓŁ / STATEK</span><span>KRAJ</span><span>KOSZT BAZOWY</span><span>STATUS</span><span/></div><div className={styles.participantTable}>{game.contacts.map(c=>{const unlockedNow=contactUnlocked(game,c);return <div className={unlockedNow?styles.participantRow:styles.participantLocked} key={c.id}><div><b>{c.name}</b><span>{c.aircraft} · {c.tier}</span></div><span>{c.country}</span><span>{money(c.fee)}</span><span className={unlockedNow?styles["status_"+c.status]:styles.status_locked}>{unlockedNow?t(game.locale,`status.${c.status}` as any):"Zablokowany"}</span><div>{!unlockedNow?<small>Sezon {c.minSeason}+ · reputacja {c.minReputation}+</small>:<>{c.status==="available"&&<button onClick={()=>invite(c.id)}>Wyślij zaproszenie</button>}{c.status==="invited"&&<small>Odpowiedź: {c.replyAt&&formatDate(c.replyAt)}</small>}{c.status==="interested"&&<button onClick={()=>open(c.id)}>Warunki umowy</button>}{c.status==="confirmed"&&<small>Umowa aktywna</small>}{c.status==="declined"&&<small>Niedostępny</small>}</>}</div></div>})}</div></div>}

function Marketing({game,run}:{game:SaveGame;run:(id:string)=>void}){const dept=game.departments.find(d=>d.id==="marketing")!;const done=game.marketing.filter(c=>c.completed).length;const demand=ticketDemandPerDay(game);return <div className={styles.modulePage}><ModuleHeader eyebrow="KOMUNIKACJA" title="Marketing i popyt" description="Buduj rozpoznawalność wydarzenia. Kampanie zwiększają zainteresowanie publiczności, ale ich skuteczność wykorzystasz dopiero przy odpowiednim programie i rozsądnej cenie biletów." meta={`Rozpoznawalność ${game.awareness}%`}/><section className={styles.marketingSummary}><Kpi label="Rozpoznawalność" value={game.awareness+"%"} note="świadomość marki wydarzenia"/><Kpi label="Poziom Marketingu" value={dept.level+" / 4"} note="odblokowuje większe kampanie"/><Kpi label="Prognoza popytu" value={game.ticketing.salesOpened?demand+" / dzień":"—"} note="przy obecnej cenie"/><Kpi label="Zrealizowane kampanie" value={done+" / "+game.marketing.length} note="działania w tym sezonie"/></section><div className={styles.campaignGrid}>{game.marketing.map(c=><CampaignCard key={c.id} campaign={c} level={dept.level} cash={game.cash} run={run}/>)}</div></div>}

function CampaignCard({campaign,level,cash,run}:{campaign:MarketingCampaign;level:number;cash:number;run:(id:string)=>void}){const locked=level<campaign.requiredLevel;return <article className={campaign.completed?styles.campaignDone:styles.campaignCard}><header><div><span>KAMPANIA</span><h3>{campaign.name}</h3></div><b>{campaign.completed?"ZAKOŃCZONA":`+ ${campaign.awareness}% ZASIĘGU`}</b></header><p>{campaign.description}</p><div className={styles.campaignMeta}><span>Koszt<b>{money(campaign.cost)}</b></span><span>Wymagany Marketing<b>Poziom {campaign.requiredLevel}</b></span></div><footer><button disabled={campaign.completed||locked||campaign.cost>cash} onClick={()=>run(campaign.id)}>{campaign.completed?"Zrealizowano":locked?`Wymaga poziomu ${campaign.requiredLevel}`:campaign.cost>cash?"Brak środków":"Uruchom kampanię"}</button></footer></article>}

function Tickets({game,open,adjust}:{game:SaveGame;open:()=>void;adjust:(delta:number)=>void}){const confirmed=game.contacts.filter(c=>c.status==="confirmed").length;const revenue=game.transactions.filter(x=>x.category==="ticketing"&&x.amount>0).reduce((a,b)=>a+b.amount,0);const demand=ticketDemandPerDay(game);const fill=Math.round(game.ticketing.sold/game.ticketing.capacity*100);const potential=Math.max(0,game.ticketing.capacity-game.ticketing.sold)*game.ticketing.price;return <div className={styles.modulePage}><ModuleHeader eyebrow="SPRZEDAŻ" title="Bilety i frekwencja" description="Cena wpływa na tempo sprzedaży. Mocniejszy program, wyższa reputacja, marketing i zbliżający się termin wydarzenia zwiększają popyt." meta={game.ticketing.salesOpened?"SPRZEDAŻ AKTYWNA":"SPRZEDAŻ ZAMKNIĘTA"}/><section className={styles.ticketSummary}><Kpi label="Sprzedane bilety" value={game.ticketing.sold.toLocaleString("pl-PL")} note={`z ${game.ticketing.capacity.toLocaleString("pl-PL")} dostępnych`}/><Kpi label="Przychód z biletów" value={money(revenue)} note="zaksięgowany w finansach"/><Kpi label="Dzienne tempo" value={game.ticketing.salesOpened?demand.toLocaleString("pl-PL"):"—"} note="prognoza przy obecnych warunkach"/><Kpi label="Wypełnienie" value={fill+"%"} note="sprzedana pojemność"/></section><section className={styles.ticketWorkspace}><article className={styles.surface}><PanelHead overline="CENNIK" title="Cena biletu" meta={money(game.ticketing.price)}/><div className={styles.priceControl}><button onClick={()=>adjust(-10)}>− 10 PLN</button><strong>{money(game.ticketing.price)}</strong><button onClick={()=>adjust(10)}>+ 10 PLN</button></div><p>Niższa cena poprawia tempo sprzedaży, ale ogranicza maksymalny przychód. Zbyt wysoka cena wymaga silnego programu i wysokiej rozpoznawalności.</p>{!game.ticketing.salesOpened&&<button className={styles.ticketOpen} disabled={confirmed<1} onClick={open}>{confirmed<1?"Potwierdź najpierw uczestnika":"Otwórz sprzedaż"}</button>}</article><article className={styles.surface}><PanelHead overline="PROGNOZA" title="Stan sprzedaży" meta={fill+"%"}/><div className={styles.salesProgress}><i><em style={{width:fill+"%"}}/></i><div><span>{game.ticketing.sold.toLocaleString("pl-PL")} sprzedanych</span><b>{game.ticketing.capacity.toLocaleString("pl-PL")} pojemności</b></div></div><div className={styles.salesForecast}><span>Potencjalna wartość pozostałej puli<b>{money(potential)}</b></span><span>Rozpoznawalność wydarzenia<b>{game.awareness}%</b></span><span>Potwierdzony program<b>{confirmed} uczestników</b></span></div></article></section></div>}

function Team({game,upgrade}:{game:SaveGame;upgrade:(id:Department["id"])=>void}){const payroll=monthlyPayroll(game);const avg=(game.departments.reduce((a,d)=>a+d.level,0)/game.departments.length).toFixed(1);return <div className={styles.modulePage}><ModuleHeader eyebrow="ORGANIZACJA" title="Zespół i departamenty" description="Rozwijaj kompetencje organizacji. Wyższy poziom zespołu odblokowuje trudniejsze zadania operacyjne, ale zwiększa stałe koszty sezonu." meta={`${money(payroll)} / mies.`}/><section className={styles.teamSummary}><Kpi label="Miesięczny koszt zespołu" value={money(payroll)} note="naliczany wraz z upływem czasu"/><Kpi label="Średni poziom" value={avg} note="w czterech departamentach"/><Kpi label="Gotówka" value={money(game.cash)} note="dostępne środki"/></section><div className={styles.departmentGrid}>{game.departments.map(d=><DepartmentCard key={d.id} department={d} cash={game.cash} upgrade={upgrade}/>)}</div></div>}

function DepartmentCard({department,cash,upgrade}:{department:Department;cash:number;upgrade:(id:Department["id"])=>void}){const cost=Math.round(department.upgradeCost*(1+(department.level-1)*.45));return <article className={styles.departmentCard}><header><div><span>DEPARTAMENT</span><h3>{department.name}</h3></div><b>POZIOM {department.level}/4</b></header><p>{department.description}</p><div className={styles.levelTrack}>{[1,2,3,4].map(x=><i key={x} className={x<=department.level?styles.levelOn:""}/>)}</div><div className={styles.departmentStats}><span>Utrzymanie / mies.<b>{money(department.monthlyCost*department.level)}</b></span><span>Następny poziom<b>{department.level>=4?"MAX":money(cost)}</b></span></div><footer><button disabled={department.level>=4||cost>cash} onClick={()=>upgrade(department.id)}>{department.level>=4?"Maksymalny poziom":cost>cash?"Brak środków":"Rozwiń departament"}</button></footer></article>}

function Operations({game,complete}:{game:SaveGame;complete:(id:string)=>void}){const done=game.operations.filter(x=>x.completed).length;const opReady=operationReadiness(game);return <div className={styles.modulePage}><ModuleHeader eyebrow="OPERACJE" title="Gotowość operacyjna" description="Realizuj przygotowania wymagane do bezpiecznego przeprowadzenia AirShow. Zadania zależą od kompetencji odpowiednich departamentów." meta={`${done}/${game.operations.length} zakończone`}/><section className={styles.operationsSummary}><Kpi label="Gotowość operacyjna" value={opReady+"%"} note="zrealizowane zadania"/><Kpi label="Otwarte zadania" value={String(game.operations.length-done)} note="wymagają decyzji"/><Kpi label="Budżet operacyjny" value={money(game.cash)} note="dostępne środki"/></section><div className={styles.operationList}>{game.operations.map(op=>{const dept=game.departments.find(d=>d.id===op.department)!;const locked=dept.level<op.requiredLevel;return <article key={op.id} className={op.completed?styles.operationDone:styles.operationCard}><div className={styles.operationStatus}>{op.completed?"GOTOWE":locked?"ZABLOKOWANE":"DO REALIZACJI"}</div><div><h3>{op.title}</h3><p>{op.description}</p><div className={styles.operationMeta}><span>Departament <b>{dept.name}</b></span><span>Wymagany poziom <b>{op.requiredLevel}</b></span><span>Koszt <b>{money(op.cost)}</b></span><span>Gotowość <b>+{op.readiness}%</b></span></div></div><button disabled={op.completed||locked||op.cost>game.cash} onClick={()=>complete(op.id)}>{op.completed?"Zakończone":locked?`Wymaga poziomu ${op.requiredLevel}`:op.cost>game.cash?"Brak środków":"Zrealizuj zadanie"}</button></article>})}</div></div>}


function FlightProgram({game,add,update,remove}:{game:SaveGame;add:(contactId:number)=>void;update:(id:string,patch:{start?:string;duration?:number;buffer?:number})=>void;remove:(id:string)=>void}){const confirmed=game.contacts.filter(c=>c.status==="confirmed");const issues=flightProgramIssues(game);const ready=flightProgramReady(game);const unscheduled=confirmed.filter(c=>!game.flightProgram.some(slot=>slot.contactId===c.id));const sorted=[...game.flightProgram].sort((a,b)=>a.start.localeCompare(b.start));return <div className={styles.modulePage}><ModuleHeader eyebrow="FLIGHT PROGRAM" title="Harmonogram pokazów" description="Ułóż kolejność lotów, pilnuj buforów technicznych i usuń konflikty. Event Day nie zostanie dopuszczony bez kompletnego, poprawnego programu." meta={ready?"PROGRAM GOTOWY":`${issues.length} problemów`}/><section className={styles.programSummary}><Kpi label="Potwierdzeni uczestnicy" value={String(confirmed.length)} note="aktywny program"/><Kpi label="Zaplanowane sloty" value={String(game.flightProgram.length)} note="w harmonogramie"/><Kpi label="Konflikty / braki" value={String(issues.length)} note={ready?"brak problemów":"wymaga korekty"}/><Kpi label="Okno pokazów" value="10:00–18:00" note="operacyjny zakres dnia"/></section>{unscheduled.length>0&&<section className={styles.programPool}><PanelHead overline="DO ZAPLANOWANIA" title="Potwierdzeni uczestnicy bez slotu" meta={String(unscheduled.length)}/><div>{unscheduled.map(c=><button key={c.id} onClick={()=>add(c.id)}><span><b>{c.name}</b><small>{c.aircraft}</small></span><strong>DODAJ DO PROGRAMU</strong></button>)}</div></section>}<section className={styles.programBoard}><PanelHead overline="HARMONOGRAM" title="Program lotniczy" meta={ready?"VALID":"DO POPRAWY"}/>{sorted.length===0?<p className={styles.programEmpty}>Brak zaplanowanych pokazów. Najpierw podpisz umowy z uczestnikami i dodaj ich do programu.</p>:sorted.map(slot=>{const contact=game.contacts.find(c=>c.id===slot.contactId);if(!contact)return null;return <article className={styles.programSlot} key={slot.id}><div className={styles.programTime}><input aria-label="Godzina rozpoczęcia" type="time" min="10:00" max="18:00" step="300" value={slot.start} onChange={e=>update(slot.id,{start:e.target.value})}/><span>do {flightSlotEnd(slot)}</span></div><div className={styles.programAct}><b>{contact.name}</b><span>{contact.aircraft} · {contact.country}</span></div><div className={styles.programControl}><span>Pokaz</span><button onClick={()=>update(slot.id,{duration:slot.duration-5})}>−</button><b>{slot.duration} min</b><button onClick={()=>update(slot.id,{duration:slot.duration+5})}>+</button></div><div className={styles.programControl}><span>Bufor</span><button onClick={()=>update(slot.id,{buffer:slot.buffer-5})}>−</button><b>{slot.buffer} min</b><button onClick={()=>update(slot.id,{buffer:slot.buffer+5})}>+</button></div><button className={styles.programRemove} onClick={()=>remove(slot.id)}>USUŃ</button></article>})}</section>{issues.length>0&&<section className={styles.programIssues}><span>WALIDACJA PROGRAMU</span>{issues.map((issue,i)=><div key={`${issue}-${i}`}><b>!</b><p>{issue}</p></div>)}</section>}</div>}

function Infrastructure({game,build}:{game:SaveGame;build:(id:string)=>void}){const done=game.infrastructure.filter(x=>x.completed).length;const readinessGain=game.infrastructure.filter(x=>x.completed).reduce((sum,x)=>sum+x.readiness,0);const committed=game.transactions.filter(x=>x.category==="infrastructure"&&x.amount<0).reduce((sum,x)=>sum-x.amount,0);return <div className={styles.modulePage}><ModuleHeader eyebrow="LOTNISKO I TEREN" title="Infrastruktura wydarzenia" description="Przygotuj lotnisko, strefy publiczności i zaplecze awaryjne. Każda inwestycja wymaga kompetencji zespołu i bezpośrednio zwiększa gotowość AirShow." meta={`${done}/${game.infrastructure.length} gotowe`}/><section className={styles.infrastructureSummary}><Kpi label="Gotowe projekty" value={`${done} / ${game.infrastructure.length}`} note="uruchomiona infrastruktura"/><Kpi label="Wpływ na gotowość" value={`+${readinessGain}%`} note="z ukończonych inwestycji"/><Kpi label="Nakłady infrastrukturalne" value={money(committed)} note="wydatki w tym sezonie"/><Kpi label="Dostępne środki" value={money(game.cash)} note="saldo organizacji"/></section><div className={styles.infrastructureGrid}>{game.infrastructure.map(project=><InfrastructureCard key={project.id} project={project} game={game} build={build}/>)}</div></div>}

function InfrastructureCard({project,game,build}:{project:InfrastructureProject;game:SaveGame;build:(id:string)=>void}){const dept=game.departments.find(d=>d.id===project.department)!;const locked=dept.level<project.requiredLevel;return <article className={project.completed?styles.infrastructureDone:styles.infrastructureCard}><header><div><span>PROJEKT INFRASTRUKTURALNY</span><h3>{project.name}</h3></div><b>{project.completed?"GOTOWE":locked?"ZABLOKOWANE":"DO REALIZACJI"}</b></header><p>{project.description}</p><div className={styles.infrastructureMeta}><span>Koszt<b>{money(project.cost)}</b></span><span>Odpowiedzialny dział<b>{dept.name}</b></span><span>Wymagany poziom<b>{project.requiredLevel}</b></span><span>Gotowość<b>+{project.readiness}%</b></span></div><footer><button disabled={project.completed||locked||project.cost>game.cash} onClick={()=>build(project.id)}>{project.completed?"Zrealizowano":locked?`Wymaga poziomu ${project.requiredLevel}`:project.cost>game.cash?"Brak środków":"Zrealizuj inwestycję"}</button></footer></article>}

function Sponsors({game,contact,negotiate,accept}:{game:SaveGame;contact:(id:number)=>void;negotiate:(id:number)=>void;accept:(id:number)=>void}){const partners=game.sponsors.filter(s=>s.status==="partner");const secured=partners.reduce((sum,s)=>sum+(s.offer??0),0);const liability=totalSponsorPenalty(game);const fulfilled=partners.reduce((sum,s)=>sum+sponsorCommitmentProgress(game,s).filter(c=>c.fulfilled).length,0);const totalCommitments=partners.reduce((sum,s)=>sum+s.commitments.length,0);return <div className={styles.modulePage}><ModuleHeader eyebrow="KOMERCJA" title="Sponsorzy i partnerzy" description="Negocjuj wartość kontraktów, pilnuj wyłączności branżowej i dowoź zapisane świadczenia. Niewypełnione zobowiązania są rozliczane po Event Day." meta={partners.length+" aktywnych · "+money(secured)}/><section className={styles.sponsorSummary}><Kpi label="Przychód sponsorski" value={money(secured)} note="podpisane partnerstwa"/><Kpi label="Aktywne rozmowy" value={String(game.sponsors.filter(s=>["contacted","offered"].includes(s.status)).length)} note="kontakty i oferty"/><Kpi label="Zobowiązania" value={fulfilled+" / "+totalCommitments} note="spełnione świadczenia"/><Kpi label="Ryzyko kar" value={money(liability)} note={liability>0?"potencjalne rozliczenie po Event Day":"brak bieżącego ryzyka"}/></section><div className={styles.sponsorGrid}>{game.sponsors.map(sp=><SponsorCard key={sp.id} game={game} sponsor={sp} contact={contact} negotiate={negotiate} accept={accept}/>)}</div></div>}

function SponsorCard({game,sponsor,contact,negotiate,accept}:{game:SaveGame;sponsor:Sponsor;contact:(id:number)=>void;negotiate:(id:number)=>void;accept:(id:number)=>void}){const labels={prospect:"Potencjalny partner",contacted:"Oczekiwanie na odpowiedź",offered:"Oferta otrzymana",partner:"Aktywny sponsor",declined:"Brak współpracy"} as const;const locked=game.reputation<sponsor.minReputation;const conflict=sponsorConflict(game,sponsor);const progress=sponsorCommitmentProgress(game,sponsor);const penalty=sponsorPenalty(game,sponsor);const risk=sponsorNegotiationRisk(game,sponsor);return <article className={styles.sponsorCard}><header><div><span>{sponsor.tier} · {sponsor.industry}</span><h3>{sponsor.name}</h3></div><b className={styles["sponsor_"+sponsor.status]}>{labels[sponsor.status]}</b></header><div className={styles.sponsorValue}><span>WARTOŚĆ UMOWY</span><strong>{sponsor.offer?money(sponsor.offer):"od "+money(sponsor.baseOffer)}</strong></div><p>{sponsor.requirement}</p><div className={styles.sponsorMeta}><span>Wymagana reputacja <b>{sponsor.minReputation}</b></span><span>Bonus za potwierdzony pokaz <b>+{money(sponsor.perConfirmedAct)}</b></span><span>Wyłączność <b>{sponsor.exclusiveGroup.toUpperCase()}</b></span><span>Kara maksymalna <b>{Math.round(sponsor.penaltyRate*100)}%</b></span></div>{(sponsor.status==="offered"||sponsor.status==="partner")&&<div className={styles.sponsorCommitments}><span>ZOBOWIĄZANIA UMOWY</span>{progress.map(item=><div key={item.metric+item.label} className={item.fulfilled?styles.commitmentDone:styles.commitmentOpen}><i>{item.fulfilled?"✓":"!"}</i><p><b>{item.label}</b><small>{item.current} / {item.target}</small></p></div>)}{sponsor.status==="partner"&&<div className={styles.sponsorPenaltyLine}><span>Przewidywana kara przy obecnym stanie</span><b className={penalty>0?styles.expense:styles.good}>{money(penalty)}</b></div>}</div>}{sponsor.status==="offered"&&<div className={styles.sponsorOfferMeta}><span><small>Oferta ważna do</small><b>{sponsor.offerExpiresAt?formatDate(sponsor.offerExpiresAt):"—"}</b></span><span><small>Rundy negocjacji</small><b>{sponsor.negotiationRound} / 2</b></span><span><small>Ryzyko kolejnej rundy</small><b className={risk==="high"?styles.riskHigh:risk==="medium"?styles.riskMedium:styles.riskLow}>{risk==="high"?"Wysokie":risk==="medium"?"Średnie":"Niskie"}</b></span></div>}<footer>{sponsor.status==="prospect"&&<button disabled={locked||Boolean(conflict)} onClick={()=>contact(sponsor.id)}>{conflict?"Konflikt: "+conflict.name:locked?"Wymaga reputacji "+sponsor.minReputation:"Rozpocznij rozmowy"}</button>}{sponsor.status==="contacted"&&<span>Odpowiedź: {sponsor.replyAt&&formatDate(sponsor.replyAt)}</span>}{sponsor.status==="offered"&&<><button disabled={sponsor.negotiationRound>=2} onClick={()=>negotiate(sponsor.id)}>{sponsor.negotiationRound>=2?"Limit negocjacji":"Negocjuj ofertę"}</button><button className={styles.primarySmall} disabled={Boolean(conflict)} onClick={()=>accept(sponsor.id)}>{conflict?"Wyłączność zablokowana":"Podpisz umowę"}</button></>}{sponsor.status==="partner"&&<span>Umowa aktywna · rozliczenie po Event Day</span>}{sponsor.status==="declined"&&<span>Spróbuj ponownie w kolejnym sezonie</span>}</footer></article>}

function EventDay({game,run,step,decide,nextSeason}:{game:SaveGame;run:()=>void;step:()=>void;decide:(choice:"a"|"b")=>void;nextSeason:(scaleId:ScaleId)=>void}){const checks=eventDayChecks(game);const ready=checks.every(c=>c.passed);const days=daysBetween(game.currentDate,game.career.eventDate);const result=game.eventResult;const [nextScale,setNextScale]=useState<ScaleId>(game.career.scaleId);const nextBudget=nextSeasonBudget(game,nextScale);const program=sortedFlightProgram(game);const live=game.eventDay.status==="running";const pending=game.eventDay.pendingIssue;const current=program[game.eventDay.currentIndex];const currentContact=current?game.contacts.find(c=>c.id===current.contactId):null;return <div className={styles.modulePage}><ModuleHeader eyebrow="EVENT DAY" title={result?"Sezon "+game.season+" zakończony":live?"Live Operations":"Final approval"} description={result?"Podsumowanie sezonu i decyzja o kolejnym etapie kariery organizatora.":live?"Prowadź wydarzenie slot po slocie. Reaguj na opóźnienia i sytuacje operacyjne bez utraty kontroli nad całym programem.":"Ostatni audyt przed otwarciem bram. Krytyczne obszary muszą być gotowe, zanim wydarzenie zostanie dopuszczone do realizacji."} meta={result?result.score+"/100":live?"LIVE · +"+game.eventDay.delay+" MIN":days===0?"DZISIAJ":"D-"+days}/>{result?<><section className={styles.eventResult}><div className={styles.resultScore}><span>WYNIK SEZONU {String(game.season).padStart(2,"0")}</span><strong>{result.score}</strong><b>/ 100 · {result.grade}</b></div><div className={styles.resultGrid}><Kpi label="Frekwencja" value={result.attendance.toLocaleString("pl-PL")} note={result.attendanceRate+"% dostępnej pojemności"}/><Kpi label="Wykonane pokazy" value={game.eventDay.completedSlotIds.length+" / "+program.length} note={game.eventDay.canceledSlotIds.length+" odwołanych"}/><Kpi label="Opóźnienie końcowe" value={game.eventDay.delay+" min"} note="wpływ na wynik operacyjny"/><Kpi label="Saldo końcowe" value={money(game.cash)} note="środki po sezonie"/></div><div className={styles.resultMessage}><Trophy size={20}/><div><b>{result.grade==="Excellent"?"Wydarzenie klasy premium":result.grade==="Strong"?"Mocny sezon organizatora":"Sezon dowieziony operacyjnie"}</b><p>Wynik uwzględnia rzeczywisty przebieg Event Day, wykonanie programu i decyzje operacyjne.</p></div></div></section><section className={styles.nextSeason}><div className={styles.nextSeasonIntro}><span>KARIERA / SEZON {String(game.season+1).padStart(2,"0")}</span><h3>Zaplanuj kolejny AirShow.</h3><p>Wybierz skalę następnego sezonu. Zachowasz reputację i poziomy departamentów, a 30% dodatniego salda oraz premia za wynik zasilą nowy budżet.</p></div><div className={styles.nextScaleGrid}>{scales.map(scale=>{const budget=nextSeasonBudget(game,scale.id);return <button key={scale.id} onClick={()=>setNextScale(scale.id)} className={nextScale===scale.id?styles.nextScaleActive:styles.nextScaleCard}><span>{scale.tone}</span><strong>{scale.label}</strong><small>{scale.audience}</small><b>{money(budget.total)}</b></button>})}</div><div className={styles.nextBudget}><span><small>Budżet bazowy</small><b>{money(nextBudget.base)}</b></span><span><small>30% salda</small><b>+{money(nextBudget.carryover)}</b></span><span><small>Premia za wynik</small><b>+{money(nextBudget.performanceBonus)}</b></span><span><small>Budżet otwarcia</small><b>{money(nextBudget.total)}</b></span></div><button className={styles.eventLaunch} onClick={()=>nextSeason(nextScale)}>ROZPOCZNIJ SEZON {String(game.season+1).padStart(2,"0")}</button>{game.seasonHistory.length>0&&<div className={styles.seasonHistory}><span>HISTORIA KARIERY</span>{game.seasonHistory.map(h=><div key={h.season}><b>Sezon {String(h.season).padStart(2,"0")}</b><span>{h.grade} · {h.score}/100</span><span>{h.attendance.toLocaleString("pl-PL")} widzów</span></div>)}</div>}</section></>:live?<><section className={styles.liveSummary}><Kpi label="Postęp programu" value={game.eventDay.currentIndex+" / "+program.length} note="rozpatrzone sloty"/><Kpi label="Wykonane" value={String(game.eventDay.completedSlotIds.length)} note="pokazy zakończone"/><Kpi label="Odwołane" value={String(game.eventDay.canceledSlotIds.length)} note="utracone pozycje programu"/><Kpi label="Opóźnienie" value={game.eventDay.delay+" min"} note="łączny poślizg dnia"/></section>{pending?<section className={styles.liveDecision}><span>DECYZJA OPERACYJNA</span><h3>{pending.title}</h3><p>{pending.description}</p><div>{pending.choices.map(choice=><button key={choice.id} onClick={()=>decide(choice.id)}><b>{choice.label}</b><span>{choice.description}</span><strong>{(choice.cancel?"ODWOŁANIE SLOTU":choice.delay>0?"+"+choice.delay+" MIN":"BEZ OPÓŹNIENIA")+" · SCORE "+(choice.score>0?"+":"")+choice.score}</strong></button>)}</div></section>:<section className={styles.liveControl}><div><span>NASTĘPNY SLOT</span><h3>{currentContact?currentContact.name:"Program zakończony"}</h3><p>{current?current.start+" · "+(currentContact?.aircraft??"")+" · "+current.duration+" min + "+current.buffer+" min buforu":"Brak kolejnych slotów."}</p></div><button onClick={step}>{current?"URUCHOM NASTĘPNY SLOT":"ZAKOŃCZ EVENT DAY"}</button></section>}<section className={styles.liveTimeline}>{program.map((slot,index)=>{const contact=game.contacts.find(c=>c.id===slot.contactId);const done=game.eventDay.completedSlotIds.includes(slot.id);const canceled=game.eventDay.canceledSlotIds.includes(slot.id);const active=index===game.eventDay.currentIndex&&!pending;return <article key={slot.id} className={canceled?styles.liveCanceled:done?styles.liveDone:active?styles.liveActive:styles.livePending}><span>{slot.start}</span><div><b>{contact?.name??"Uczestnik"}</b><small>{slot.duration} min · bufor {slot.buffer} min</small></div><strong>{canceled?"ODWOŁANY":done?"WYKONANY":active?"NASTĘPNY":"OCZEKUJE"}</strong></article>})}</section><section className={styles.liveLog}><PanelHead overline="LIVE LOG" title="Dziennik operacyjny" meta={game.eventDay.log.length+" wpisów"}/>{game.eventDay.log.map((entry,i)=><p key={i}>{entry}</p>)}</section></>:<><section className={styles.eventGate}><div><span>STATUS DOPUSZCZENIA</span><strong className={ready?styles.good:styles.warn}>{ready?"READY FOR EVENT DAY":"NOT CLEARED"}</strong><p>{ready?"Wszystkie krytyczne warunki są spełnione. Możesz rozpocząć realizację wydarzenia.":"Uzupełnij brakujące obszary. AirShow nie zostanie uruchomiony bez minimalnego poziomu bezpieczeństwa i gotowości."}</p></div><div className={styles.eventGateScore}><span>GOTOWOŚĆ</span><b>{readiness(game)}%</b></div></section><section className={styles.eventChecklist}>{checks.map(c=><article key={c.id} className={c.passed?styles.checkPass:styles.checkFail}><span>{c.passed?"✓":"!"}</span><div><b>{c.label}</b><small>{c.detail}</small></div><strong>{c.passed?"GOTOWE":"WYMAGANE"}</strong></article>)}</section><button className={styles.eventLaunch} disabled={!ready} onClick={run}>{ready?"OTWÓRZ EVENT DAY":"EVENT DAY ZABLOKOWANY"}</button></>}</div>}

function Finance({game}:{game:SaveGame}){const spent=game.transactions.filter(x=>x.amount<0).reduce((a,b)=>a-b.amount,0);const sponsors=game.transactions.filter(x=>x.category==="sponsor"&&x.amount>0).reduce((a,b)=>a+b.amount,0);const tickets=game.transactions.filter(x=>x.category==="ticketing"&&x.amount>0).reduce((a,b)=>a+b.amount,0);return <div className={styles.modulePage}><ModuleHeader eyebrow="FINANSE" title="Kontrola budżetu" description="Każde zobowiązanie i przychód trafia do historii finansowej. Tu kontrolujesz płynność sezonu i wpływ decyzji komercyjnych." meta={money(game.cash)}/><section className={styles.financeSummary}><Kpi label="Sponsorzy" value={money(sponsors)} note="przychód z partnerstw"/><Kpi label="Bilety" value={money(tickets)} note="sprzedaż publiczności"/><Kpi label="Wydatki" value={money(spent)} note="łączne obciążenia"/><Kpi label="Dostępne środki" value={money(game.cash)} note={`budżet startowy ${money(game.career.budget)}`}/></section><article className={styles.surface}><PanelHead overline="REJESTR" title="Historia transakcji" meta={`${game.transactions.length} pozycji`}/><div className={styles.ledger}>{game.transactions.map(x=><div key={x.id}><span>{formatDate(x.date)}</span><b>{x.label}</b><strong className={x.amount>=0?styles.good:styles.expense}>{x.amount>=0?"+":""}{money(x.amount)}</strong></div>)}</div></article></div>}

function Module({section}:{section:string}){const m=modules[section]??modules.operacje;return <div className={styles.modulePage}><ModuleHeader eyebrow={m.eyebrow} title={m.title} description={m.description} meta="W ROZWOJU"/><div className={styles.moduleRoadmap}>{m.items.map((x,i)=><article key={x}><span>0{i+1}</span><div><b>{x}</b><p>Moduł został przygotowany w strukturze aplikacji i będzie rozwijany jako część symulacji sezonu.</p></div><ArrowUpRight size={17}/></article>)}</div></div>}

function IncidentModal({game,resolve}:{game:SaveGame;resolve:(choice:"a"|"b")=>void}){const incident=game.activeIncident;if(!incident)return null;return <div className={styles.modalBackdrop}><section className={styles.incidentModal}><span className={incident.kind==="crisis"?styles.incidentCrisis:styles.incidentOpportunity}>{incident.kind==="crisis"?"KRYZYS OPERACYJNY":"SZANSA SEZONOWA"}</span><h2>{incident.title}</h2><p>{incident.description}</p><div className={styles.incidentChoices}>{incident.choices.map(choice=><button key={choice.id} onClick={()=>resolve(choice.id)}><div><b>{choice.label}</b><span>{choice.description}</span></div><strong>{formatIncidentEffect(choice.effect)}</strong></button>)}</div><small className={styles.incidentLock}>Dalsze przesuwanie czasu jest wstrzymane do momentu podjęcia decyzji.</small></section></div>}

function formatIncidentEffect(effect:{cash?:number;reputation?:number;awareness?:number;readiness?:number}){const parts:string[]=[];if(effect.cash)parts.push(`${effect.cash>0?"+":""}${money(effect.cash)}`);if(effect.reputation)parts.push(`REP ${effect.reputation>0?"+":""}${effect.reputation}`);if(effect.awareness)parts.push(`ZASIĘG ${effect.awareness>0?"+":""}${effect.awareness}`);if(effect.readiness)parts.push(`GOTOWOŚĆ ${effect.readiness>0?"+":""}${effect.readiness}`);return parts.length?parts.join(" · "):"Bez bezpośredniego kosztu"}

function Contract({game,contact,close,sign,negotiate}:{game:SaveGame;contact:Contact;close:()=>void;sign:(id:number)=>void;negotiate:(id:number)=>void}){const base=participantBaseTotal(contact);const total=Math.round(base*(1-contact.agreedDiscount/100));const risk=participantNegotiationRisk(game,contact);const expired=Boolean(contact.offerExpiresAt&&contact.offerExpiresAt<game.currentDate);const roundsLeft=Math.max(0,2-contact.negotiationRound);return <div className={styles.modalBackdrop}><section className={styles.contract}><button className={styles.close} onClick={close}><X size={19}/></button><span className={styles.eyebrow}>WARUNKI UCZESTNICTWA</span><h2>{contact.name}</h2><p>{contact.aircraft} · {contact.country} · {contact.tier}</p><div className={styles.offerStrip}><span><small>Oferta ważna do</small><b>{contact.offerExpiresAt?formatDate(contact.offerExpiresAt):"—"}</b></span><span><small>Rundy negocjacji</small><b>{contact.negotiationRound} / 2</b></span><span><small>Aktualny rabat</small><b>{contact.agreedDiscount}%</b></span><span><small>Ryzyko kolejnej rundy</small><b className={risk==="high"?styles.riskHigh:risk==="medium"?styles.riskMedium:styles.riskLow}>{risk==="high"?"Wysokie":risk==="medium"?"Średnie":"Niskie"}</b></span></div><div className={styles.costList}><Cost label="Opłata za udział" value={contact.fee}/><Cost label="Hotel i obsługa gości" value={contact.hotel}/><Cost label="Paliwo" value={contact.fuel}/><Cost label="Obsługa naziemna" value={contact.support}/>{contact.agreedDiscount>0&&<Cost label={`Rabat negocjacyjny −${contact.agreedDiscount}%`} value={-(base-total)}/>}<Cost label="Łączne zobowiązanie" value={total} total/></div><div className={styles.requirementBox}><ShieldCheck size={18}/><div><b>Wymagania operacyjne</b><p>Bezpieczny parking statku powietrznego, obsługa naziemna, slot treningowy, transport załogi i odprawa operacyjna.</p></div></div><div className={styles.negotiationNote}><b>{expired?"Oferta wygasła":roundsLeft===0?"Osiągnięto limit negocjacji":risk==="high"?"Kolejna runda może zakończyć rozmowy":risk==="medium"?"Zespół może zaakceptować tylko część oczekiwań":"Masz dobrą pozycję negocjacyjną"}</b><span>Każda kolejna runda jest trudniejsza. Maksymalny łączny rabat wynosi 12%.</span></div><div className={styles.balanceAfter}><span>Saldo po podpisaniu</span><b>{money(game.cash-total)}</b></div><div className={styles.modalActions}><button disabled={expired||roundsLeft===0} onClick={()=>negotiate(contact.id)}>NEGOCJUJ WARUNKI</button><button disabled={expired||total>game.cash} onClick={()=>sign(contact.id)}>AKCEPTUJ I PODPISZ</button></div></section></div>}

function Kpi({label,value,note}:{label:string;value:string;note:string}){return <article className={styles.kpi}><span>{label}</span><b>{value}</b><small>{note}</small></article>}
function PanelHead({overline,title,meta}:{overline:string;title:string;meta:string}){return <header className={styles.panelHead}><div><span>{overline}</span><h3>{title}</h3></div><b>{meta}</b></header>}
function ModuleHeader({eyebrow,title,description,meta}:{eyebrow:string;title:string;description:string;meta:string}){return <header className={styles.moduleHeader}><div><span>{eyebrow}</span><h2>{title}</h2><p>{description}</p></div><b>{meta}</b></header>}
function Cost({label,value,total}:{label:string;value:number;total?:boolean}){return <div className={total?styles.costTotal:""}><span>{label}</span><b>{money(value)}</b></div>}
